const sourceIds = ['question:rm-js-17', 'question:rm-js-1', 'coding-task:js-digit-sum'];
const items = $input.all();
const response = items[0]?.json;
const invalid = () => { throw new Error('Unexpected staging source-check response'); };
if (items.length !== 1 || !response || response.brand !== 'devshark' || !Array.isArray(response.packets) || !Array.isArray(response.held) || response.packets.length > 3 || response.held.length > 3 || !Number.isSafeInteger(response.dropped) || response.dropped < 0 || response.dropped > 20) invalid();
const packets = new Map();
for (const packet of response.packets) {
  if (!packet || !sourceIds.includes(packet.sourceId) || packets.has(packet.sourceId) || typeof packet.eligible !== 'boolean' || typeof packet.contentHash !== 'string' || !/^[a-f0-9]{64}$/.test(packet.contentHash)) invalid();
  packets.set(packet.sourceId, packet);
}
const held = new Set();
for (const item of response.held) {
  if (!item || !sourceIds.includes(item.sourceId) || held.has(item.sourceId)) invalid();
  held.add(item.sourceId);
}
const sources = sourceIds.map(sourceId => {
  const packet = packets.get(sourceId);
  return { sourceId, contentHash: packet?.contentHash ?? null, status: held.has(sourceId) ? 'held' : packet ? (packet.eligible ? 'eligible' : 'ineligible') : 'missing' };
});
return [{ json: { status: sources.some(source => source.status === 'missing') ? 'incomplete' : 'checked', requestedCount: 3, packetCount: packets.size, eligibleCount: sources.filter(source => source.status === 'eligible').length, heldCount: held.size, missingCount: sources.filter(source => source.status === 'missing').length, droppedCount: response.dropped, sources } }];
